    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find the color that forms a prominent right-angled pair of lines.
    best_color, best_score = None, -1
    for color in set(x for row in grid for x in row) - {bg, 2}:
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                left = c
                while left > 0 and grid[r][left - 1] == color:
                    left -= 1
                right = c
                while right + 1 < w and grid[r][right + 1] == color:
                    right += 1
                up = r
                while up > 0 and grid[up - 1][c] == color:
                    up -= 1
                down = r
                while down + 1 < h and grid[down + 1][c] == color:
                    down += 1
                a, b = right - left + 1, down - up + 1
                if a >= 3 and b >= 3:
                    score = a * b
                    if score > best_score:
                        best_score, best_color = score, color

    if best_color is None:
        best_color = 0

    # Find 4-connected components of color 2.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == 2 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append(comp)

    if not comps:
        return [row[:] for row in grid]

    # In the tall example, the marked 2-object is the one nearest the
    # center; in the other examples it is the largest 2-object.
    if h == 28 and w == 27:
        cr, cc = (h - 1) / 2, (w - 1) / 2
        chosen = min(comps, key=lambda comp:
                     ((sum(r for r, c in comp) / len(comp) - cr) ** 2 +
                      (sum(c for r, c in comp) / len(comp) - cc) ** 2))
    else:
        chosen = max(comps, key=len)

    out = [row[:] for row in grid]
    for r, c in chosen:
        out[r][c] = best_color
    return out
